function dp_panel_migration_version(string $semantic,int $schema):PanelMigrationVersion{return PanelMigrationVersion::make($semantic,$schema);}

/** @return array{0:PanelAtomicMigrationStore,1:Closure,2:Closure,3:string} */
function dp_panel_migration_store(Context $t,string $name):array{
	$now='2026-07-14T12:00:00+00:00';$token=0;$run=0;
	$clock=static function()use(&$now):string{return$now;};
	$advance=static function(int $seconds)use(&$now):void{$now=(new DateTimeImmutable($now))->modify('+'.$seconds.' seconds')->format(DATE_ATOM);};
	$tokens=static function()use(&$token):string{$token++;return str_pad('migration-token-'.$token,64,'x');};
	$runs=static function()use(&$run):string{$run++;return'migration-run-'.$run;};
	$directory=$t->tempDirectory('panel-migrations-'.$name);
	return[new PanelAtomicMigrationStore($directory,64,$clock,$tokens,$runs),$advance,$clock,$directory];
}

/** @return array{0:PanelMigrationRegistry,1:PanelMigrationDefinition,2:PanelMigrationDefinition} */
function dp_panel_migration_registry():array{
	$first=PanelMigrationDefinition::make('orders.normalize','orders',dp_panel_migration_version('1.0.0',1),dp_panel_migration_version('1.1.0',2),static function(PanelMigrationContext $context):PanelMigrationBatch{
		$data=$context->data();$items=is_array($data['items']??null)?$data['items']:[];$offset=(int)($context->cursor()??0);$end=min(count($items),$offset+$context->limit());
		for($index=$offset;$index<$end;$index++){$items[$index]['normalized']=true;}$data['items']=$items;$checkpoint=['password'=>'batch-secret','offset'=>$end];
		return$end<count($items)?PanelMigrationBatch::more($data,$end,$end-$offset,$checkpoint):PanelMigrationBatch::complete($data,$end-$offset,$checkpoint);
	},['batch_size'=>2,'capabilities'=>['orders.write'],'preflight'=>static fn(PanelMigrationContext $context):array=>['ok'=>isset($context->data()['items']),'issues'=>['items missing']],'down'=>static function(PanelMigrationContext $context):PanelMigrationBatch{$data=$context->data();foreach(is_array($data['items']??null)?$data['items']:[]as$index=>$item){unset($item['normalized']);$data['items'][$index]=$item;}return PanelMigrationBatch::complete($data,count($data['items']??[]));}]);
	$second=PanelMigrationDefinition::make('orders.index','orders',dp_panel_migration_version('1.1.0',2),dp_panel_migration_version('2.0.0',3),static function(PanelMigrationContext $context):PanelMigrationBatch{$data=$context->data();$data['index']=array_column($data['items']??[],'id');return PanelMigrationBatch::complete($data,count($data['index']));},['dependencies'=>['orders.normalize'],'batch_size'=>10,'capabilities'=>['orders.write'],'down'=>static function(PanelMigrationContext $context):PanelMigrationBatch{$data=$context->data();unset($data['index']);return PanelMigrationBatch::complete($data,1);}]);
	return[new PanelMigrationRegistry([$first,$second]),$first,$second];
}

test('migration value objects enforce versions integrity redaction and safe manifests',static function(Context $t):void{
