	$t->same('1.0.0',$v1->semantic());$t->same(1,$v1->schema());$t->isTrue($v1->before($v2));$t->same(-1,$v1->compare($v2));$t->isTrue($v1->equals(PanelMigrationVersion::fromArray($v1->jsonSerialize())));$t->same('1.0.0@1',(string)$v1);
	$t->throws(static fn()=>dp_panel_migration_version('1.0',1),InvalidArgumentException::class);$t->throws(static fn()=>dp_panel_migration_version('01.0.0',1),InvalidArgumentException::class);$t->throws(static fn()=>dp_panel_migration_version('1.0.0',-1),InvalidArgumentException::class);
	$t->isFalse(dp_panel_migration_version('1.0.0',5)->before(dp_panel_migration_version('2.0.0',4)));
	$digest=PanelMigrationIntegrity::digest(['b'=>2,'a'=>1]);$t->same($digest,PanelMigrationIntegrity::digest(['a'=>1,'b'=>2]));$t->same(null,PanelMigrationIntegrity::tenant(''));$t->same('tenant-1',PanelMigrationIntegrity::tenant('tenant-1'));$t->throws(static fn()=>PanelMigrationIntegrity::identifier('bad id'),InvalidArgumentException::class);$t->throws(static fn()=>PanelMigrationIntegrity::canonicalJson(new stdClass()),InvalidArgumentException::class);
	$redacted=PanelMigrationIntegrity::redact(['password'=>'open','nested'=>['api_key'=>'key','message'=>'token=abc normal']]);$t->same('[REDACTED]',$redacted['password']);$t->same('[REDACTED]',$redacted['nested']['api_key']);$t->contains('token=[REDACTED]',$redacted['nested']['message']);
	$state=PanelMigrationState::make('orders','tenant-1',$v1,['secret'=>'state-only'],['base'],4);$t->same('orders',$state->scope());$t->same('tenant-1',$state->tenant());$t->same(['secret'=>'state-only'],$state->data());$t->same(['base'],$state->applied());$t->same(4,$state->revision());$t->same($state->digest(),PanelMigrationState::fromStored($state->stored())->digest());$t->notContains('state-only',json_encode($state,JSON_THROW_ON_ERROR));
	$evolved=$state->evolved($v2,['done'=>true],['base','next']);$t->same(5,$evolved->revision());$t->throws(static fn()=>PanelMigrationState::make('orders',null,$v1,[],[],-1),InvalidArgumentException::class);$stored=$state->stored();$stored['digest']=str_repeat('0',64);$t->throws(static fn()=>PanelMigrationState::fromStored($stored),RuntimeException::class);unset($stored['digest']);$t->throws(static fn()=>PanelMigrationState::fromStored($stored),RuntimeException::class);
	$context=new PanelMigrationContext('orders','tenant-1','orders.normalize','up',['rows'=>[]],3,25,['secret'=>'value'],true,['id'=>'actor']);$t->same('orders',$context->scope());$t->same('tenant-1',$context->tenant());$t->same('orders.normalize',$context->migrationId());$t->same('up',$context->direction());$t->same(['rows'=>[]],$context->data());$t->same(3,$context->cursor());$t->same(25,$context->limit());$t->isTrue($context->dryRun());$t->same(['id'=>'actor'],$context->actor());$t->same('[REDACTED]',$context->jsonSerialize()['checkpoint']['secret']);
	$t->throws(static fn()=>new PanelMigrationContext('orders',null,'migration','sideways',[],null,1,[],false,null),InvalidArgumentException::class);$t->throws(static fn()=>new PanelMigrationContext('orders',null,'migration','up',[],null,0,[],false,null),InvalidArgumentException::class);
	$batch=PanelMigrationBatch::more(['row'=>1],'next',1,['token'=>'unsafe'],['password'=>'unsafe']);$t->isFalse($batch->done());$t->same('next',$batch->nextCursor());$t->same(1,$batch->processed());$t->same(['row'=>1],$batch->data());$t->same('[REDACTED]',$batch->jsonSerialize()['checkpoint']['token']);$t->same('[REDACTED]',$batch->jsonSerialize()['compensation']['password']);$t->isTrue(PanelMigrationBatch::complete([],0)->done());$t->throws(static fn()=>PanelMigrationBatch::more([],'',1),InvalidArgumentException::class);$t->throws(static fn()=>PanelMigrationBatch::complete([],-1),InvalidArgumentException::class);
})->tag('panel','migrations','values','security')->maxMillis(3000);

