test('atomic migration runner dry-runs batches resumes idempotently and never leaks state or bearer proofs',static function(Context $t):void{
	[$store,,,$directory]=dp_panel_migration_store($t,'execute');[$registry]=dp_panel_migration_registry();$seed=$store->seed('orders','tenant-a',dp_panel_migration_version('1.0.0',1),['items'=>[['id'=>1],['id'=>2],['id'=>3],['id'=>4],['id'=>5]],'password'=>'state-secret']);$authorizations=[];$runner=new PanelMigrationRunner($store,$registry,static function(string $ability,mixed $actor,array $context)use(&$authorizations):bool{$authorizations[]=$ability;return$actor==='admin'&&isset($context['plan']);});
	$plan=$runner->plan('orders','tenant-a',dp_panel_migration_version('2.0.0',3),'2026-07-14T12:00:00Z');$t->same($store,$runner->store());$t->same($registry,$runner->registry());$t->same($registry,$runner->planner()->registry());
	$blocked=$runner->preflight($plan,'guest',[]);$t->same('blocked',$blocked->status());$t->isTrue($blocked->terminal());$t->isFalse($blocked->successful());$t->contains('Missing migration capabilities',json_encode($blocked,JSON_THROW_ON_ERROR));$t->contains('not authorized',json_encode($blocked,JSON_THROW_ON_ERROR));
	$dry=$runner->execute($plan,'admin',['orders.write'],'worker-a',true);$t->same('preflight',$dry->status());$t->same($seed->digest(),$store->state('orders','tenant-a')->digest());
	$partial=$runner->execute($plan,'admin',['orders.write'],'worker-a',false,1);$t->same('running',$partial->status());$t->same(1,$partial->jsonSerialize()['batch_count']);$t->same(1,$partial->jsonSerialize()['checkpoint_count']);$runId=$partial->runId();$t->isTrue(is_string($runId));$snapshot=$store->snapshot((string)$runId);$t->isTrue($snapshot instanceof PanelMigrationSnapshot);$t->same($seed->digest(),$snapshot?->stateDigest());$t->same($runId,$snapshot?->runId());$t->notContains('state-secret',json_encode($snapshot,JSON_THROW_ON_ERROR));
	$complete=$runner->resume($plan,'admin',['orders.write'],'worker-b',100);$t->same('completed',$complete->status());$t->isTrue($complete->successful());$t->isTrue($complete->terminal());$t->same(2,$complete->jsonSerialize()['step_index']);$t->same(4,$complete->jsonSerialize()['batch_count']);$t->same(10,$complete->jsonSerialize()['processed']);$t->same(1,$complete->jsonSerialize()['resumes']);$final=$store->state('orders','tenant-a');$t->same('2.0.0',$final->version()->semantic());$t->same([1,2,3,4,5],$final->data()['index']);$t->isTrue($final->data()['items'][4]['normalized']);$t->same(['orders.index','orders.normalize'],$final->applied());
	$json=json_encode($complete,JSON_THROW_ON_ERROR);$t->notContains('batch-secret',$json);$t->notContains('state-secret',$json);$t->contains('[REDACTED]',$json);$t->same($runId,$store->reportByPlan($plan->digest())?->runId());$t->same($runId,$store->report((string)$runId)?->runId());$t->same(null,$store->report('missing-run'));$t->same(null,$store->reportByPlan('bad'));
	$replayed=$runner->execute($plan,'admin',['orders.write'],'worker-c');$t->same('completed',$replayed->status());$t->same($runId,$replayed->runId());$t->isTrue(count($store->changesSince(0,100)['changes'])>0);$manifest=$store->manifest();$t->isTrue($manifest['capabilities']['atomic_batches']);$t->isTrue($manifest['capabilities']['backup_snapshots']);$t->same(0,$manifest['active_leases']);$t->same($manifest,$store->jsonSerialize());$t->isTrue(count($authorizations)>=4);$store->seed('orders','tenant-a',$final->version(),$final->data(),$final->applied());$t->same('blocked',$runner->preflight($plan,'admin',['orders.write'])->status());
	$raw='';foreach(glob($directory.DIRECTORY_SEPARATOR.'*.json')?:[]as$file){$raw.=(string)file_get_contents($file);}$t->notContains('migration-token-',$raw);
})->tag('panel','migrations','runner','resume','security')->maxMillis(7000);

test('migration rollback compensates reversible batches and snapshot-restores irreversible work',static function(Context $t):void{
	[$store]=dp_panel_migration_store($t,'rollback');[$registry]=dp_panel_migration_registry();$store->seed('orders','tenant-a',dp_panel_migration_version('1.0.0',1),['items'=>[['id'=>1],['id'=>2]]]);$untrusted=new PanelMigrationRunner($store,$registry);$plan=$untrusted->plan('orders','tenant-a',dp_panel_migration_version('2.0.0',3),'2026-07-14T12:00:00Z');$t->same('blocked',$untrusted->preflight($plan,null,['orders.write'])->status());$t->same('blocked',$untrusted->execute($plan,null,['orders.write'])->status());$t->isFalse($untrusted->trustedExecution());$t->isFalse($untrusted->manifest()['authorization']['configured']);$t->isTrue($untrusted->manifest()['authorization']['default_deny']);$runner=$untrusted->allowTrustedExecution();$t->isFalse($runner===$untrusted);$t->isTrue($runner->trustedExecution());$t->isTrue($runner->manifest()['authorization']['trusted_execution']);$completed=$runner->execute($plan,null,['orders.write']);$t->same('completed',$completed->status());$t->same('blocked',$untrusted->rollback($plan,null,['orders.write'])->status());$t->same('blocked',$runner->rollback($plan,null,['bad grant'])->status());$rolling=$runner->rollback($plan,null,['orders.write'],maxBatches:1);$t->same('rolling_back',$rolling->status());$t->same(0,$rolling->jsonSerialize()['rollback_index']);$rolled=$runner->rollback($plan,null,['orders.write']);$t->same('rolled_back',$rolled->status());$t->isTrue($rolled->successful());$t->same('compensation',$rolled->jsonSerialize()['rollback_mode']);$restored=$store->state('orders','tenant-a');$t->same('1.0.0',$restored->version()->semantic());$t->same([['id'=>1],['id'=>2]],$restored->data()['items']);$t->same([],$restored->applied());
	[$fallbackStore]=dp_panel_migration_store($t,'rollback-fallback');$irreversible=PanelMigrationDefinition::make('settings.breaking','settings',dp_panel_migration_version('0.0.0',0),dp_panel_migration_version('1.0.0',1),static function(PanelMigrationContext $context):PanelMigrationBatch{$data=$context->data();$data['changed']=true;return PanelMigrationBatch::complete($data,1);});$fallbackRegistry=new PanelMigrationRegistry([$irreversible]);$fallbackStore->seed('settings',null,dp_panel_migration_version('0.0.0',0),['original'=>true]);$fallbackRunner=(new PanelMigrationRunner($fallbackStore,$fallbackRegistry))->allowTrustedExecution();$fallbackPlan=$fallbackRunner->plan('settings',null,dp_panel_migration_version('1.0.0',1),'2026-07-14T12:00:00Z');$fallbackRunner->execute($fallbackPlan);$blocked=$fallbackRunner->rollback($fallbackPlan,null,[],owner:'rollback',snapshotFallback:false);$t->same('failed',$blocked->status());$fallback=$fallbackRunner->rollback($fallbackPlan);$t->same('rolled_back',$fallback->status());$t->same('snapshot_restore',$fallback->jsonSerialize()['rollback_mode']);$t->same(['original'=>true],$fallbackStore->state('settings')->data());
})->tag('panel','migrations','rollback','backup')->maxMillis(7000);

test('migration store rejects stale plans and stale fences and recovers expired executions',static function(Context $t):void{
	[$store,$advance]=dp_panel_migration_store($t,'recovery');[$registry,$definition]=dp_panel_migration_registry();$store->seed('orders','tenant-a',dp_panel_migration_version('1.0.0',1),['items'=>[['id'=>1]]]);$runner=(new PanelMigrationRunner($store,$registry))->allowTrustedExecution();$plan=$runner->plan('orders','tenant-a',dp_panel_migration_version('2.0.0',3),'2026-07-14T12:00:00Z');
	$lease=$store->acquire('orders','tenant-a','worker-a',5);$t->isTrue($lease instanceof PanelMigrationLease);$leaseManifest=$lease->jsonSerialize();$t->same($lease->tokenFingerprint(),$leaseManifest['token_fingerprint']);$t->notContains($lease->token(),json_encode($leaseManifest,JSON_THROW_ON_ERROR));$t->same(null,$store->acquire('orders','tenant-a','worker-b',5));$t->throws(static fn()=>$store->seed('orders','tenant-a',dp_panel_migration_version('1.0.0',1),[]),PanelMigrationConflict::class);$begun=$store->begin($lease,$plan,'actor');$t->same('running',$begun->status());$contended=$runner->execute($plan,null,['orders.write'],'worker-b');$t->same('blocked',$contended->status());$t->contains('Another worker owns the migration scope lease',json_encode($contended,JSON_THROW_ON_ERROR));$t->throws(static fn()=>$store->complete($lease,(string)$begun->runId(),$plan),PanelMigrationConflict::class);
	$advance(6);$recovered=$store->recoverExpired();$t->same(1,count($recovered));$t->same('paused',$recovered[0]->status());$t->throws(static fn()=>$store->renew($lease),PanelMigrationLeaseLost::class);$t->same([],$store->recoverExpired());
