test('migration adapter conformance and optional platform domain expose the production lifecycle truthfully',static function(Context $t):void{
	[$store]=dp_panel_migration_store($t,'conformance');$report=(new PanelAdapterConformanceRunner())->run(PanelAdapterConformanceCatalog::migrationStore(),$store,['allow_destructive'=>true,'scope'=>'migration_conformance']);$t->isTrue($report->passed());$t->same(1,$report->summary()['passed']);$t->same(0,$report->summary()['failed']);
	[$registry,$first]=dp_panel_migration_registry();$disabled=['operations'=>false,'distributed_operations'=>false,'data'=>false,'workflows'=>false,'automation'=>false,'authentication'=>false,'notifications'=>false,'media'=>false,'localization'=>false,'preferences'=>false,'collaboration'=>false,'relations'=>false,'security'=>false,'development'=>false,'extensions'=>false,'platform'=>false];$platform=PanelPlatform::defaults(['state_root'=>$t->tempDirectory('panel-platform-migrations'),'migrations'=>['definitions'=>$registry->all(),'snapshot_retention'=>16,'authorize'=>static fn():bool=>true]]+$disabled);$t->isTrue($platform->manifest()->available('migrations'));$t->isTrue($platform->manifest()->configured('migrations'));$t->isTrue($platform->manifest()->ready('migrations'));$t->same($platform->migrationStore(),$platform->migrationRunner()->store());$t->same($platform->migrationRegistry(),$platform->migrationRunner()->registry());$t->isTrue(in_array('migrations',$platform->jsonSerialize()['metadata']['enabled_domains'],true));
	$platform->migrationStore()->seed('orders','tenant-a',dp_panel_migration_version('1.0.0',1),['items'=>[]]);$plan=$platform->migrationPlan('orders','tenant-a',dp_panel_migration_version('2.0.0',3),'2026-07-14T12:00:00Z');$t->same(['orders.normalize','orders.index'],$plan->migrationIds());$replacement=PanelMigrationDefinition::make('orders.normalize','orders',dp_panel_migration_version('1.0.0',1),dp_panel_migration_version('1.1.0',2),static fn(PanelMigrationContext $context):PanelMigrationBatch=>PanelMigrationBatch::complete($context->data()));$platform->registerMigration($replacement,true);$t->same($replacement,$platform->migrationRegistry()->get('orders.normalize'));
	$without=PanelPlatform::defaults(['state_root'=>$t->tempDirectory('panel-platform-without-migrations')]+$disabled);$t->isFalse($without->has('migrations.store'));$t->isFalse($without->manifest()->configured('migrations'));$denied=PanelPlatform::defaults(['state_root'=>$t->tempDirectory('panel-platform-denied-migrations'),'migrations'=>['definitions'=>$registry->all()]]+$disabled);$denied->migrationStore()->seed('orders','tenant-a',dp_panel_migration_version('1.0.0',1),['items'=>[]]);$deniedPlan=$denied->migrationPlan('orders','tenant-a',dp_panel_migration_version('2.0.0',3),'2026-07-14T12:00:00Z');$t->same('blocked',$denied->migrationRunner()->preflight($deniedPlan,'system',['orders.write'])->status());$t->isFalse($denied->migrationRunner()->manifest()['authorization']['configured']);$t->throws(static fn()=>PanelPlatform::defaults(['state_root'=>$t->tempDirectory('panel-platform-invalid-migrations'),'migrations'=>['definitions'=>['bad']]]+$disabled),InvalidArgumentException::class);
})->tag('panel','migrations','platform','conformance')->maxMillis(10000);
